'use strict';
const I18N={
 zh:{title:'臺灣學術活動週覽',subtitle:'數學、物理與天文的近期學術活動。',range:'範圍',upcoming:'未來七天',recent:'過去七天',institution:'機構',allInstitutions:'全部機構',search:'搜尋',sourceStatus:'來源狀態',footer:'活動資訊以原始機構公告為準。',events:'筆活動',generated:'資料產生',noEvents:'此篩選條件下沒有活動。',partial:'部分來源未完整更新，請查看來源狀態。',recurring:'定期活動',today:'今天'},
 en:{title:'Taiwan Science Agenda',subtitle:'Recent academic events in mathematics, physics and astronomy.',range:'Range',upcoming:'Next 7 days',recent:'Past 7 days',institution:'Institution',allInstitutions:'All institutions',search:'Search',sourceStatus:'Source status',footer:'Please refer to the original institution announcement for authoritative event information.',events:'events',generated:'Generated',noEvents:'No events match these filters.',partial:'Some sources were not fully updated. See source status.',recurring:'Recurring',today:'Today'}
};
const SOURCE_NAMES_EN={
 ncts:{short:'NCTS Mathematics',name:'National Center for Theoretical Sciences — Mathematics Division'},
 as_math:{short:'AS Mathematics',name:'Institute of Mathematics, Academia Sinica'},
 ntu_phys:{short:'NTU Physics',name:'Department of Physics, National Taiwan University'},
 ntu_math:{short:'NTU Mathematics',name:'Department of Mathematics, National Taiwan University'},
 astro:{short:'NTU Astrophysics',name:'Graduate Institute of Astrophysics, National Taiwan University'},
 asiaa:{short:'ASIAA',name:'Academia Sinica Institute of Astronomy and Astrophysics'},
 lecospa:{short:'LeCosPA',name:'Leung Center for Cosmology and Particle Astrophysics, National Taiwan University'},
 iams:{short:'IAMS',name:'Institute of Atomic and Molecular Sciences, Academia Sinica'}
};
let data=null,lang=localStorage.getItem('lang')||'zh',rangeMode='upcoming';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'');
function tr(k){return I18N[lang][k]||k}
function sourceLabel(source){if(!source)return '';if(lang==='en')return SOURCE_NAMES_EN[source.id]?.short||source.short_name_en||source.name_en||source.id;return source.short_name||source.name||source.id}
function sourceTitle(source){if(!source)return '';if(lang==='en')return SOURCE_NAMES_EN[source.id]?.name||source.name_en||sourceLabel(source);return source.name||sourceLabel(source)}
function localDate(iso){return new Date(iso+'T00:00:00+08:00')}
function todayTW(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei'}).format(new Date())}
function fmtDate(iso){return new Intl.DateTimeFormat(lang==='zh'?'zh-TW':'en-US',{timeZone:'Asia/Taipei',month:'long',day:'numeric',weekday:'long'}).format(localDate(iso))}
function fmtGenerated(v){if(!v)return '—';const d=new Date(v);return new Intl.DateTimeFormat(lang==='zh'?'zh-TW':'en-US',{timeZone:'Asia/Taipei',dateStyle:'medium',timeStyle:'short'}).format(d)}
function applyI18n(){document.documentElement.lang=lang==='zh'?'zh-Hant':'en';document.querySelectorAll('[data-i18n]').forEach(el=>{el.textContent=tr(el.dataset.i18n)});$('langToggle').textContent=lang==='zh'?'English':'中文';document.title=tr('title')}
function populateSources(){const sel=$('sourceFilter'),current=sel.value;sel.replaceChildren();const all=document.createElement('option');all.value='all';all.textContent=tr('allInstitutions');sel.append(all);for(const s of data?.sources||[]){const o=document.createElement('option');o.value=s.id;o.textContent=sourceLabel(s);o.title=sourceTitle(s);sel.append(o)}if([...sel.options].some(o=>o.value===current))sel.value=current}
function inRange(e,mode){const base=localDate(todayTW());const a=new Date(base),b=new Date(base);if(mode==='upcoming')b.setUTCDate(b.getUTCDate()+6);else{a.setUTCDate(a.getUTCDate()-7);b.setUTCDate(b.getUTCDate()-1)}const sd=localDate(e.start_date),ed=localDate(e.end_date);return ed>=a&&sd<=b&&(mode==='upcoming'||ed<base)}
function render(){if(!data)return;populateSources();const q=$('searchInput').value.trim().toLocaleLowerCase(),src=$('sourceFilter').value,mode=rangeMode;const events=(data.events||[]).filter(e=>inRange(e,mode)&&(src==='all'||e.source_id===src)&&(!q||[e.title,e.speaker,e.location,e.kind].join(' ').toLocaleLowerCase().includes(q)));$('meta').textContent=`${events.length} ${tr('events')} · ${tr('generated')}: ${fmtGenerated(data.generated_at)}`;const bad=(data.sources||[]).some(s=>s.status!=='ok');$('notice').hidden=!bad;$('notice').textContent=bad?tr('partial'):'';const root=$('events');root.replaceChildren();if(!events.length){const p=document.createElement('p');p.className='empty';p.textContent=tr('noEvents');root.append(p)}else{const groups=Map.groupBy?Map.groupBy(events,e=>e.start_date):events.reduce((m,e)=>(m.set(e.start_date,[...(m.get(e.start_date)||[]),e]),m),new Map());for(const [date,rows] of groups){const sec=document.createElement('section');sec.className='day';const h=document.createElement('h2');h.textContent=fmtDate(date)+(date===todayTW()?` · ${tr('today')}`:'');sec.append(h);for(const e of rows){const article=document.createElement('article');article.className='event';const tm=document.createElement('div');tm.className='event-time';tm.textContent=e.start_time?`${e.start_time}${e.end_time?'–'+e.end_time:''}`:'—';const so=document.createElement('div');so.className='event-source';const institution=(data.sources||[]).find(s=>s.id===e.source_id)||{id:e.source_id};so.textContent=sourceLabel(institution);so.title=sourceTitle(institution);const body=document.createElement('div');const h3=document.createElement('h3');const a=document.createElement('a');a.href=e.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=esc(e.title);h3.append(a);if(e.recurring){const b=document.createElement('span');b.className='badge';b.textContent=tr('recurring');h3.append(b)}body.append(h3);const detail=document.createElement('div');detail.className='event-detail';detail.textContent=[e.speaker,e.location].filter(Boolean).join(' · ');body.append(detail);article.append(tm,so,body);sec.append(article)}root.append(sec)}}const sr=$('sources');sr.replaceChildren();for(const s of data.sources||[]){const row=document.createElement('div');row.className='source-row';const a=document.createElement('a');a.href=s.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=sourceLabel(s);a.title=sourceTitle(s);const st=document.createElement('span');st.className='status '+(s.status||'');st.textContent=s.status||'unknown';row.append(a,st);sr.append(row)}}
async function loadEvents(){if(window.INITIAL_EVENTS!==undefined)return window.INITIAL_EVENTS;const r=await fetch('./data/events.json',{cache:'no-store'});if(!r.ok)throw new Error(`HTTP ${r.status}`);return r.json()}
async function boot(){applyI18n();try{data=await loadEvents();render()}catch(err){$('events').textContent='Unable to load event data: '+err.message}}
$('langToggle').addEventListener('click',()=>{lang=lang==='zh'?'en':'zh';localStorage.setItem('lang',lang);applyI18n();render()});document.querySelectorAll('[data-range]').forEach(button=>button.addEventListener('click',()=>{rangeMode=button.dataset.range;document.querySelectorAll('[data-range]').forEach(option=>option.setAttribute('aria-pressed',String(option===button)));render()}));for(const id of ['sourceFilter','searchInput'])$(id).addEventListener(id==='searchInput'?'input':'change',render);boot();
